const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centralValley = ee.Geometry.Polygon(
    [
      [-122.3, 39.5],
      [-121.3, 40.5],
      [-120.3, 40.0],
      [-119.5, 38.0],
      [-119.0, 36.5],
      [-120.0, 35.0],
      [-121.5, 35.5],
      [-122.5, 37.0]
    ],
    null,
    false
  ); // Defined a representative polygon for the Central Valley of California.

  const startDate = '2022-10-01';
  const endDate = '2023-03-31';
  const precipitationThresholdInches = 15;
  const scale = 5566; // CHIRPS original resolution is 0.05 degrees, which is approx 5.5 km. Use this scale or slightly larger.

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/PENTAD')
    .filterDate(startDate, endDate)
    .filterBounds(centralValley);

  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log(`Error: No CHIRPS images found for the Central Valley between ${startDate} and ${endDate}.`);
    console.log("C1");
    return;
  }
  console.log(`CHIRPS Images for period: ${collectionSize}`);

  // Sum all precipitation images in the collection for the total rainfall over the period.
  const totalPrecipitationImage = chirps.sum();

  // 3. Processing & Calculation
  // Calculate pixel count for the region to check for C2
  const countPixels = totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16 // Increase tileScale to avoid memory errors for large geometries
  });

  const validPixels = await countPixels.get('precipitation').getInfo();
  if (validPixels === 0 || validPixels === null) {
    console.log("Error: No valid pixels found in the Central Valley after image summation (might be out of bounds for the dataset).");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels in region: ${validPixels}`);

  // Calculate the total mean precipitation (in mm) over the Central Valley.
  const meanPrecipitation = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).get('precipitation').getInfo();

  // 4. Validation & Final Answer
  if (meanPrecipitation === null || isNaN(meanPrecipitation)) {
    console.log("Error: Mean precipitation calculation failed (result is null or NaN).");
    console.log("C3");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const meanPrecipitationInches = meanPrecipitation / 25.4;

  console.log(`Total precipitation in Central Valley (mm): ${meanPrecipitation.toFixed(2)}`);
  console.log(`Total precipitation in Central Valley (inches): ${meanPrecipitationInches.toFixed(2)}`);
  console.log(`Threshold: ${precipitationThresholdInches} inches`);

  if (meanPrecipitationInches >= precipitationThresholdInches) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
